#!/usr/bin/env python3
import os, re
ROOT=os.path.dirname(os.path.abspath(__file__))
SRC=os.path.join(ROOT,"sources"); OUT=os.path.join(ROOT,"skills")
def w(skill, fname, text):
    d=os.path.join(OUT,skill,"references"); os.makedirs(d,exist_ok=True)
    p=os.path.join(d,fname)
    open(p,"w").write(text); print(fname, len(text)); return len(text)
total=0
LIB=os.path.join(SRC,"libre")

# ---- LibreMetaverse API catalogue ----
out=["# LibreMetaverse API Catalogue (generated from cinderblocks/libremetaverse source)\n",
"Generated by scanning the C# source of https://github.com/cinderblocks/libremetaverse (BSD-3). For each source file: namespace, declared types, and public methods, properties, and events with signatures. Use this to find the exact class to call before reading the source itself.\n"]
files=[]
for dp,dn,fn in os.walk(LIB):
    if any(x in dp for x in [".Tests","obj","bin"]): continue
    for f in fn:
        if f.endswith(".cs"): files.append(os.path.join(dp,f))
files.sort()
ntypes=0; nmethods=0
for fp in files:
    rel=os.path.relpath(fp,LIB)
    try: src=open(fp,encoding="utf-8",errors="replace").read()
    except: continue
    ns=re.search(r'^\s*namespace\s+([\w\.]+)', src, re.M)
    types=re.findall(r'^\s*public\s+(?:static\s+|abstract\s+|sealed\s+|partial\s+)*(class|struct|interface|enum|record|delegate)\s+(\w+)', src, re.M)
    if not types: continue
    methods=re.findall(r'^\s*public\s+(?:static\s+|virtual\s+|override\s+|abstract\s+|async\s+|sealed\s+)*([\w<>\[\]\?,\. ]+?)\s+(\w+)\s*\(([^;{}]*)\)\s*(?:\{|;|=>)', src, re.M)
    props=re.findall(r'^\s*public\s+(?:static\s+|virtual\s+|override\s+|abstract\s+)*([\w<>\[\]\?,\.]+)\s+(\w+)\s*\{\s*get', src, re.M)
    events=re.findall(r'^\s*public\s+event\s+([\w<>\.]+)\s+(\w+)', src, re.M)
    out.append(f"\n## {rel}\n")
    out.append(f"- Namespace: `{ns.group(1) if ns else '?'}` | Project folder: `{rel.split('/')[0]}`\n")
    for kind,name in types:
        out.append(f"- Type: {kind} `{name}`\n"); ntypes+=1
    for ret,name,args in methods:
        if name in ("get","set"): continue
        a=" ".join(args.split())[:160]
        out.append(f"  - Method: `{ret.strip()} {name}({a})`\n"); nmethods+=1
    for ret,name in props:
        out.append(f"  - Property: `{ret.strip()} {name}`\n")
    for ret,name in events:
        out.append(f"  - Event: `{ret.strip()} {name}`\n")
out.insert(2, f"Catalogue covers {len(files)} source files, {ntypes} public types, {nmethods} public methods.\n")
total+=w("secondlife_client_libraries","libremetaverse-api.md","\n".join(out))

# ---- Asset / inventory enums from LibreMetaverse.Types ----
enum_out=["# Asset and Inventory Type Enums (generated from LibreMetaverse.Types)\n"]
for dp,dn,fn in os.walk(LIB):
    for f in fn:
        if not f.endswith(".cs"): continue
        fp=os.path.join(dp,f); src=open(fp,encoding="utf-8",errors="replace").read()
        for m in re.finditer(r'public enum (\w+)([^{]*)\{([^}]*)\}', src, re.S):
            name=m.group(1)
            if name not in ("AssetType","InventoryType","InventoryCategory","PrimFlags","ObjectCategory","AttachmentPoint","BakeType","AvatarTextureIndex","AvatarTexture","TextureIndex","FaceType","MeshType","PCode","SaleType","WearableType","Eyes","Hair","Shape","Skin","Clothes","AnimType"): 
                if "Asset" not in name and "Invent" not in name and "Prim" not in name and "Texture" not in name and "Wearable" not in name and "Attach" not in name and "Bake" not in name: continue
            enum_out.append(f"\n## {name} (from {os.path.relpath(fp,LIB)})\n")
            body=m.group(3)
            # strip comments markers but keep descriptions in /// comments preceding members: simple approach list members
            for line in body.splitlines():
                s=line.strip().rstrip(",")
                if s and not s.startswith("//"):
                    enum_out.append(f"- `{s}`\n")
total+=w("secondlife_assets_mesh_texture","asset-inventory-enums.md","\n".join(enum_out))

# ---- OpenSim: OSSL + LSL API functions from source ----
OS=os.path.join(SRC,"opensim-src")
ossl=[]
for dp,dn,fn in os.walk(OS):
    for f in fn:
        if "OSSL" in f and f.endswith(".cs"):
            fp=os.path.join(dp,f); src=open(fp,encoding="utf-8",errors="replace").read()
            for m in re.finditer(r'public\s+([\w<>\[\]]+)\s+(os\w+)\s*\(([^)]*)\)', src):
                ossl.append((m.group(2), m.group(1), " ".join(m.group(3).split()), os.path.relpath(fp,OS)))
seen={}
for n,r,a,f in ossl: seen[n]=(r,a,f)
out=["# OSSL Function Reference (generated from opensim/opensim source)\n",
f"Extracted {len(seen)} os* function signatures from the OpenSimulator source tree (OSSL API implementation files). OSSL functions exist only in OpenSim, never on Agni, and each is gated by a threat level and osslEnable.ini allow lists. Verify the threat level for a function in the OpenSim wiki OSSL pages and in osslEnable.ini before relying on it for a non-owner user.\n"]
for n in sorted(seen):
    r,a,f=seen[n]
    out.append(f"\n## {n}\n")
    out.append(f"```csharp\n{r} {n}({a})\n```\n")
    out.append(f"- Implemented in: `{f}`\n")
    out.append("- Grid check required: wrap calls in a grid detection pattern or keep OpenSim-only scripts separate from SL builds. On Agni this call is a compile error, not a runtime failure.\n")
total+=w("secondlife_opensim_server","ossl-functions.md","\n".join(out))

# LSL functions implemented by OpenSim LSL_Api
lsl_impl=[]
for dp,dn,fn in os.walk(OS):
    for f in fn:
        if f.startswith("LSL_") and f.endswith(".cs"):
            fp=os.path.join(dp,f); src=open(fp,encoding="utf-8",errors="replace").read()
            for m in re.finditer(r'public\s+([\w<>\[\]]+)\s+(ll\w+)\s*\(([^)]*)\)', src):
                lsl_impl.append((m.group(2), m.group(1), " ".join(m.group(3).split()), os.path.relpath(fp,OS)))
seen={}
for n,r,a,f in lsl_impl: seen[n]=(r,a,f)
out=["# LSL Functions as Implemented by OpenSim (generated from opensim/opensim source)\n",
f"Extracted {len(seen)} ll* signatures from OpenSim's LSL_Api implementation. Where a function is missing here but exists in the canonical lsl-definitions reference, OpenSim may implement it in another partial class file or not at all. Behaviour differences between this implementation and Linden Lab's are the porting risk when moving scripts between grids.\n"]
for n in sorted(seen):
    r,a,f=seen[n]
    out.append(f"\n## {n}\n")
    out.append(f"```csharp\n{r} {n}({a})\n```\n")
    out.append(f"- OpenSim implementation: `{f}` | Canonical definition: see lsl-functions.md in secondlife_lsl_scripting.\n")
total+=w("secondlife_opensim_server","opensim-lsl-implementation.md","\n".join(out))

# OpenSim config reference from examples
for srcfile, skill, title in [("OpenSim.ini.example","secondlife_opensim_server","OpenSim.ini Configuration Reference"),("Robust.ini.example","secondlife_opensim_server","Robust.ini Configuration Reference")]:
    p=os.path.join(SRC,srcfile)
    if not os.path.exists(p): continue
    raw=open(p,encoding="utf-8",errors="replace").read()
    out=[f"# {title} (from opensim/opensim stock example)\n",
    "Reproduced and structured from the stock example file in the OpenSim repo (BSD). Comments are upstream's own. Set values in your local .ini, never by editing the .example.\n"]
    section="preamble"
    for line in raw.splitlines():
        s=line.strip()
        m=re.match(r'^\[(.+)\]$', s)
        if m: section=m.group(1); out.append(f"\n## [{section}]\n"); continue
        if s.startswith(";") or s.startswith("#"):
            out.append(f"{s.lstrip(';# ')}\n" if len(s)>2 else "")
        elif "=" in s and not s.startswith(";"):
            k,v=s.split("=",1); out.append(f"- `{k.strip()}` = `{v.strip()}`\n")
    total+=w(skill, srcfile.replace(".example","").lower().replace(".","-")+"-reference.md","\n".join(out))

# OpenSim module / source tree catalogue
out=["# OpenSim Source Tree Catalogue (generated from opensim/opensim)\n"]
tree={}
for dp,dn,fn in os.walk(OS):
    rel=os.path.relpath(dp,OS)
    if rel.startswith(("bin",".git")): continue
    cs=[f for f in fn if f.endswith(".cs")]
    if cs: tree[rel]=cs
for rel in sorted(tree):
    out.append(f"\n## {rel} ({len(tree[rel])} C# files)\n")
    for f in sorted(tree[rel]): out.append(f"- `{f}`\n")
total+=w("secondlife_opensim_server","opensim-source-tree.md","\n".join(out))

# LibreMetaverse source tree for client libraries examples + viewer cross ref
out=["# LibreMetaverse Source Tree (generated)\n"]
tree={}
for dp,dn,fn in os.walk(LIB):
    rel=os.path.relpath(dp,LIB)
    if any(x in rel for x in ["obj","bin",".git"]): continue
    cs=[f for f in fn if f.endswith(".cs")]
    if cs: tree[rel]=cs
for rel in sorted(tree):
    out.append(f"\n## {rel} ({len(tree[rel])} C# files)\n")
    for f in sorted(tree[rel]): out.append(f"- `{f}`\n")
total+=w("secondlife_client_libraries","libremetaverse-source-tree.md","\n".join(out))
print("TOTAL2:", total)
